CREATE TABLE IF NOT EXISTS exchange_rate(id INTEGER PRIMARY KEY CHECK(id=1),rate REAL NOT NULL CHECK(rate>0 AND rate<=100),version INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL);
INSERT OR IGNORE INTO exchange_rate(id,rate,updated_at) VALUES(1,3.40,'2026-09-12T04:38:10Z');
CREATE TABLE IF NOT EXISTS exchange_audit(id INTEGER PRIMARY KEY,previous_rate REAL NOT NULL,rate REAL NOT NULL,version INTEGER NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS login_attempts(key TEXT PRIMARY KEY,attempts INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS product_overrides(id INTEGER PRIMARY KEY,data TEXT NOT NULL,version INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS requests(reference TEXT PRIMARY KEY,idempotency_key TEXT UNIQUE NOT NULL,body_hash TEXT NOT NULL,data TEXT NOT NULL,summary TEXT NOT NULL,version INTEGER NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS request_files(id TEXT PRIMARY KEY,reference TEXT NOT NULL REFERENCES requests(reference),name TEXT NOT NULL,size INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS file_chunks(file_id TEXT NOT NULL REFERENCES request_files(id),part INTEGER NOT NULL,data TEXT NOT NULL,PRIMARY KEY(file_id,part));
CREATE INDEX IF NOT EXISTS requests_created_at ON requests(created_at);
